import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Open Cube OS Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"root/ARCHITECTURE.md","filePath":"root/ARCHITECTURE.md"}'),o={name:"root/ARCHITECTURE.md"};function i(r,e,c,p,l,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="open-cube-os-architecture" tabindex="-1">Open Cube OS Architecture <a class="header-anchor" href="#open-cube-os-architecture" aria-label="Permalink to &quot;Open Cube OS Architecture&quot;">​</a></h1><p>This document describes the tree as it exists in 3.0.0-WP06c - every component named below is a real file you can open. Line counts and per-directory detail live in <code>docs/data/stats.json</code> (regenerate: <code>make api-docs</code>).</p><h2 id="the-two-rings" tabindex="-1">The two rings <a class="header-anchor" href="#the-two-rings" aria-label="Permalink to &quot;The two rings&quot;">​</a></h2><p>Open Cube OS is a two-ring system:</p><ul><li><strong>L0 - provides services.</strong> A pure service kernel: the core mechanisms, the drivers, the root services and the interface surface. 3.0.0-WP03 deleted the L0 user plane entirely - the <code>oc&gt;</code> shell, every shell command, the TUI framework and the input method engine are gone; L0 finishes boot at <code>L0 ready, waiting for L1</code> and hands the machine to the default ring-3 entry.</li><li><strong>L1 - uses services.</strong> Ring-3 user applications that reach L0 capability through the extension surface (the <code>SYS_L1SVC</code> op table and the classic syscall ABI). 3.0.0-WP04 moved every command into L1: <strong>275 programs under <code>src/L1/</code></strong> (242 app folders + 8 flat <code>.c</code> + 25 flat <code>.asm</code>) - one command = one app = one folder. The default boot entry is the ring-3 <code>ush</code> shell (<code>OC_L1_APP_DECL(&quot;ush&quot;, ..., dflt=1)</code> in <code>src/L0/boot/l1_launcher.c</code>); <strong>285 commands = 274 registry apps + 11 ush built-ins, zero in L0</strong>.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>              OCBL - the in-tree bootloader (hybrid BIOS + UEFI ISO)</span></span>
<span class="line"><span>              512-byte real-mode stage 1 (El Torito / MBR) or the EFI</span></span>
<span class="line"><span>              entry -&gt; 16 -&gt; 32 -&gt; 64-bit long mode, dynamic disk scan,</span></span>
<span class="line"><span>              boot menu with a 10 s countdown (no GRUB in the chain)</span></span>
<span class="line"><span>        +-------------------------+-------------------------+</span></span>
<span class="line"><span>        |              src/L0/boot/boot.S                  |</span></span>
<span class="line"><span>        |  32-bit entry -&gt; GDT -&gt; 2 MiB identity map of    |</span></span>
<span class="line"><span>        |  the first 4 GiB -&gt; PAE+LME+PGE -&gt; long mode     |</span></span>
<span class="line"><span>        +---------------------------------------------------+</span></span>
<span class="line"><span>                               |  kmain (src/L0/boot/kmain.c)</span></span>
<span class="line"><span>        +-------------------------+-------------------------+</span></span>
<span class="line"><span>        |  PHASE 1  kernel core mechanisms                  |</span></span>
<span class="line"><span>        |    core/console (serial/fb platform text layer),  |</span></span>
<span class="line"><span>        |    IDT/PIC/exceptions, PIT, PMM/VMM/heap,         |</span></span>
<span class="line"><span>        |    scheduler/sync, userspace, registry,           |</span></span>
<span class="line"><span>        |    ACPI/PCIe/watchdog-hw/chipset, RTC/HPET        |</span></span>
<span class="line"><span>        |  PHASE 2  drivers + driver-free services          |</span></span>
<span class="line"><span>        |    VFS + ramfs (driver-free); block/USB/wireless/ |</span></span>
<span class="line"><span>        |    SD/BT/camera/misc driver families              |</span></span>
<span class="line"><span>        |  PHASE 3  driver-dependent services               |</span></span>
<span class="line"><span>        |    FAT/exFAT/ext4 + config + A/B (after block),   |</span></span>
<span class="line"><span>        |    wireless (after fs-mounted firmware),          |</span></span>
<span class="line"><span>        |    net (after NIC), snd (after the snd family)    |</span></span>
<span class="line"><span>        |  PHASE 4  interfaces ready                        |</span></span>
<span class="line"><span>        |    crash dump/crashlog/soft wdt, health monitor,  |</span></span>
<span class="line"><span>        |    update check, the OCIRE embed confirmation     |</span></span>
<span class="line"><span>        +---------------------------------------------------+</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>                     &quot;L0 ready, waiting for L1&quot;</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>                    l1 launcher -&gt; ush (ring 3)</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>          exit / failure -&gt; L0 halts honestly (reboot or the</span></span>
<span class="line"><span>          OCBL menu; the 2.x oc&gt; recovery fallback is gone)</span></span></code></pre></div><p>(The boot prints <code>boot chain N/4</code> markers for the middle phases; <code>tools/check_deps.py</code> gates the layer directions below.)</p><h2 id="the-l0-tree-3-0-0-wp03-layout" tabindex="-1">The L0 tree (3.0.0-WP03 layout) <a class="header-anchor" href="#the-l0-tree-3-0-0-wp03-layout" aria-label="Permalink to &quot;The L0 tree (3.0.0-WP03 layout)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/L0/</span></span>
<span class="line"><span>  boot/     the composition root: boot.S, long mode entry, the</span></span>
<span class="line"><span>            multiboot2 header/stub, kmain.c, the L1 launcher and the</span></span>
<span class="line"><span>            boot self-tests. May depend on every layer.</span></span>
<span class="line"><span>  core/     kernel mechanisms: scheduling, sync, timers, usermode,</span></span>
<span class="line"><span>            the panic slots (arch_exceptions), the declaration</span></span>
<span class="line"><span>            registry, the captured-output primitive, mem/, lib/</span></span>
<span class="line"><span>            (string/log/klog-ring/config-kv), console/ (the mb2</span></span>
<span class="line"><span>            framebuffer platform text layer), arch/{x86_64,arm64,</span></span>
<span class="line"><span>            riscv} and generated/.  Depends on nothing above it.</span></span>
<span class="line"><span>  drivers/  hardware drivers, one folder per family (block, nic,</span></span>
<span class="line"><span>            snd, usb, input, pci, acpi, i2c, time, wireless,</span></span>
<span class="line"><span>            bluetooth, sd, camera, misc, scsi).  No services</span></span>
<span class="line"><span>            dependencies.</span></span>
<span class="line"><span>  services/ root services - the folder is the interface facet:</span></span>
<span class="line"><span>            fs block net audio font encoding display loader</span></span>
<span class="line"><span>            selfhost ocembed | sysapi ipc klog health crash</span></span>
<span class="line"><span>            (+ time power crypto camera usb bodies).  May depend on</span></span>
<span class="line"><span>            core/ and drivers/ (and, where a real dependency</span></span>
<span class="line"><span>            exists, on other services - fs before selfhost, for</span></span>
<span class="line"><span>            example).</span></span>
<span class="line"><span>src/L1/     the ring-3 world: 275 programs (242 app folders + 8 flat</span></span>
<span class="line"><span>            .c + 25 flat .asm) - ush (the only OC_L1_APP_DECL default</span></span>
<span class="line"><span>            entry), the TUI desktop family, the editor, the Chinese</span></span>
<span class="line"><span>            console + IME, and one command per app (built by</span></span>
<span class="line"><span>            \`make l1apps\`).</span></span>
<span class="line"><span>ocbl/       OCBL, the in-tree bootloader (BIOS stage 1 + EFI entry,</span></span>
<span class="line"><span>            the boot menu, the ocbl-install target) - a separate</span></span>
<span class="line"><span>            freestanding build (ocbl/ocbl.mk). NOT part of L0.</span></span>
<span class="line"><span>ocire/      the independent recovery kernel (a separate freestanding</span></span>
<span class="line"><span>            binary, own build in ocire/ocire.mk).  NOT part of L0.</span></span></code></pre></div><p><strong>The dependency rule</strong> (enforced by <code>tools/check_deps.py</code>, run in the test matrix): <code>core/</code> must not depend on <code>drivers/</code> or <code>services/</code>; <code>drivers/</code> must not depend on <code>services/</code>. The inversions this required in WP-03 G5: the platform console stack lives in <code>core/console</code>; the klog ring is a core mechanism with the on-disk sink in <code>services/klog</code> installed as an emit hook; crash capture lives in <code>services/crash</code> and installs its handlers into the core-owned panic slots; the config store keeps the key-value mechanism in core with the fs backend installed from <code>services/fs</code>.</p><h2 id="extension-by-adding-a-file" tabindex="-1">Extension by adding a file <a class="header-anchor" href="#extension-by-adding-a-file" aria-label="Permalink to &quot;Extension by adding a file&quot;">​</a></h2><p>Nothing registers into global tables through runtime calls. A driver, a service or an L1 app declares its identity IN THE FILE THAT IMPLEMENTS IT via the <code>OC_*_DECL</code> macros (<code>core_registry.h</code>); each macro places a const descriptor into a dedicated linker section (<code>.oc_drvs</code>, <code>.oc_svcs</code>, <code>.oc_apps</code>) and <code>core_registry_collect()</code> walks the section boundaries at boot. Adding a new driver or service = adding one <code>.c</code> file in the right folder plus one declaration line - no boot-file edit, no registration call site (live-tested in the G3 evidence: one new file with one <code>OC_DRIVER_DECL</code> was collected at runtime, then removed).</p><p>The register-class L1 interfaces of v1 (<code>driver_block_register</code>, <code>driver_nic_register</code>, ...) died with the section mechanism; their operation-class siblings (read/write/send/recv/...) remain the surface (see INTERFACES.md for the full table and the v1-&gt;v2-&gt;v3 fate record).</p><h2 id="the-interface-surface" tabindex="-1">The interface surface <a class="header-anchor" href="#the-interface-surface" aria-label="Permalink to &quot;The interface surface&quot;">​</a></h2><p>Ring 3 reaches L0 through two doors:</p><ul><li>the classic syscall ABI (<code>src/L0/services/sysapi/core_syscall.h</code>, 54 syscalls), including <code>SYS_L1SVC(110)</code>: <code>(category, op, arg, out, cap)</code> routed by the registry to the owning service&#39;s <code>l1_dispatch</code>.</li><li>the categories/ops are the frozen ABI table in <code>src/L0/services/sysapi/l1svc_defs.h</code>: <strong>20 categories / 190 numbered entries</strong> (category number -&gt; the owning services/ folder; category 18 &quot;ocire&quot; is the declared exception - the OCIRE log-agent contract&#39;s ABI name, implemented by <code>services/ocembed/</code>). Ops are plain ASCII text renderers - the ring-3 side formats nothing.</li></ul><h2 id="the-boot-state-monitor-3-0-0-wp07a" tabindex="-1">The boot-state monitor (3.0.0-WP07a) <a class="header-anchor" href="#the-boot-state-monitor-3-0-0-wp07a" aria-label="Permalink to &quot;The boot-state monitor (3.0.0-WP07a)&quot;">​</a></h2><p>OCBL cannot execute while the kernel runs, so the WP07a boot-state monitor enforces the boot timeouts with a hardware watchdog relay (the 6300ESB, the same PCI device OCIRE&#39;s supervisor loop uses):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OCBL arm(30s) -&gt; handoff -&gt; kernel stage N: write stage + arm(next</span></span>
<span class="line"><span>budget) -&gt; ... -&gt; L1_READY: 1 Hz tick pets the 15 s runtime budget</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>                v (a hang stops the feeding)</span></span>
<span class="line"><span>6300ESB resets the machine (warm reset, DRAM kept)</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>OCBL boots again: reads the state area -&gt; silence &gt;= 8 s and no</span></span>
<span class="line"><span>CLEAN marker -&gt; JUDGED: writes the BOOT_FAILED record (stall point,</span></span>
<span class="line"><span>timestamp, measured silence) -&gt; screen notice -&gt; 8042 pulse</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>OCBL boots again: pending unrouted record -&gt; auto-boots OCIRE</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>OCIRE: reads the record -&gt; prints the stall point + repair advice</span></span></code></pre></div><p>The contract lives in <code>include/ocbl_state.h</code> (shared byte-for-byte by OCBL, OCOS and OCIRE):</p><ul><li><strong>State area</strong> at 0x98000 - what the kernel is doing (stage, heartbeat, the RTC clock of the last progress). The kernel only WRITES it (blind, never reads back); OCBL reads/writes; OCIRE reads. L1 applications cannot reach it: the pages sit in the supervisor-only half of every user address space (verified live by a CR3 walk at L1_READY + the badapp canary class).</li><li><strong>Reserved area</strong> at 0x9B000 - the post-mortem boot record (BOOT_FAILED vs USER_REQUEST, the stall stage, the judgment timestamp, the measured silence, a ones-complement checksum). It survives warm resets (the two addresses are the empirically proven surviving islands of the QEMU/SeaBIOS reset wipe - see <code>evidence/3_0_0_WP07a/</code>); cold boots clear it and every reader validates the magic first.</li><li><strong>Six state points</strong>: KM_AIN_ENTERED (kmain entry), SCHED_READY (core mechanisms up), DRIVERS_READY (driver families probed), SERVICES_READY (root services up), L1_LAUNCHED (ush started), L1_READY (ush serving - its first syscall).</li><li><strong>Phase budgets</strong>: 30 s (boot start -&gt; stage 1), 10 s per middle phase, 30 s (L1_LAUNCHED -&gt; L1_READY), 15 s runtime heartbeat.</li><li><strong>Judgment</strong>: OCBL computes the silence (RTC now minus the last kernel progress); &gt;= 8 s without the CLEAN marker = a judged failure (a healthy boot progresses every second, so a manual warm reset measures &lt; ~4 s and is NOT a failure).</li><li><strong>Clean reboots</strong>: the kernel marks the state area CLEAN before its deliberate 8042 reboot, so a normal <code>reboot</code> never produces a failure record.</li><li><strong>User requests</strong>: picking the OCIRE entry in the OCBL menu writes a USER_REQUEST record - the exact distinction OCIRE reports (&quot;requested by the user&quot; vs a judged failure with repair advice).</li></ul><p>The whole chain is driven live (real watchdog resets, real 8042 pulses, both record kinds, every phase budget, the runtime hang, the manual-reset discrimination) by <code>tools/wp07a_state_e2e.py</code>; the transcripts are archived under <code>evidence/3_0_0_WP07a/</code>.</p><h2 id="the-ocire-embed-3-0-0-wp03-g4" tabindex="-1">The OCIRE embed (3.0.0-WP03 G4) <a class="header-anchor" href="#the-ocire-embed-3-0-0-wp03-g4" aria-label="Permalink to &quot;The OCIRE embed (3.0.0-WP03 G4)&quot;">​</a></h2><p>When the OCIRE recovery supervisor (see <code>ocire/</code>) hands the machine to OCOS via kexec, it passes boot facts on the command line (<code>oc.mb= oc.log= oc.logsecs= oc.wdt= oc.agent=1</code>) and attaches its log agent as a multiboot2 module. <code>services/ocembed/</code> closes the loop on the OCOS side: it parses the facts, writes SIGNAL_OK into the recovery mailbox, disarms the i6300esb watchdog inside the supervised 60 s window, spawns the agent as the protected <code>ocire_guard</code> process (kill is refused by sys_kill), serves the guard-only <code>L1SVC_CAT_OCIRE</code> channel (boot-log append + kernel-log snapshot) and arms whole-disk write protection on the recovery disk. On a normal OCBL boot no fact is present and the service stays dormant. The five regression properties (partition isolation, boot signal, bidirectional interfaces, process protection, whole-disk hard protection) are tested end-to-end by <code>tools/run_ocire_supervised_tests.py</code>.</p><h2 id="kernel-abilities-that-stayed" tabindex="-1">Kernel abilities that stayed <a class="header-anchor" href="#kernel-abilities-that-stayed" aria-label="Permalink to &quot;Kernel abilities that stayed&quot;">​</a></h2><p>The kernel log ring (+ the <code>/var/log/kernel.log</code> sink), the health monitor (1 s sampling + alarms), crash capture (core dump + crashlog + the panic path), the soft watchdog slots and the hardware watchdog (TCO/WDAT) are all L0-side mechanisms - the L0 COMMAND entries that used to drive them died with the user plane; the mechanisms themselves boot-armed and testable (the batteries in <code>evidence/3_0_0_wp03_*</code>).</p>`,26)])])}const m=s(o,[["render",i]]);export{g as __pageData,m as default};
